// 1. ИНИЦИАЛИЗАЦИЯ ДАННЫХ
function getSafeArray(nodeName) {
  try { return $(nodeName).all().map(item => item.json); } catch (e) { return []; }
}
function getSafeFirst(nodeName) {
  try { const data = $(nodeName).all(); return data.length > 0 ? data[0].json : {}; } catch (e) { return {}; }
}

let garminNode = getSafeFirst('Webhook') || {};
if (Object.keys(garminNode).length === 0) garminNode = getSafeFirst('Webhook1');
let garmin = garminNode.body || garminNode;

const nutritionList = getSafeArray('Get Nutrition');
const climateRecords = getSafeArray('Get Climate');
const calendarItems = getSafeArray('Get Calendar Events');
const rescueData = getSafeFirst('Get RescueTime');

const weather = getSafeFirst('Get Weather'); 
const weatherDeltas = getSafeFirst('Перепады давления');

const rnd = (val) => (val !== null && val !== undefined && !isNaN(val) && val !== '') ? Math.round(Number(val) * 10) / 10 : null;

// 2. ДАТЫ И ВРЕМЕННЫЕ МЕТКИ
let btMs = 0; 
let wtMs = 0;

if (garmin.bedtime && garmin.wakeup_time) {
  let btStr = String(garmin.bedtime).replace(' ', 'T');
  if (!btStr.includes('+') && !btStr.endsWith('Z')) btStr += '+10:00';
  btMs = new Date(btStr).getTime();

  let wtStr = String(garmin.wakeup_time).replace(' ', 'T');
  if (!wtStr.includes('+') && !wtStr.endsWith('Z')) wtStr += '+10:00';
  wtMs = new Date(wtStr).getTime();
}

// Дата строки пробуждения (например, 2026-08-19)
let todayStr = garmin.date;
let startOfTodayMs = todayStr ? new Date(`${todayStr}T00:00:00+10:00`).getTime() : 0;

// Вчерашний день (сутки накануне сна: 2026-08-18 00:00 - 23:59)
let startOfYesterdayMs = startOfTodayMs - 24 * 60 * 60 * 1000;
let endOfYesterdayMs = startOfTodayMs;

const netSleep = garmin.sleep_total_min || 0;
const awake = garmin.awake_time_min || 0;
const inBed = netSleep + awake;
const lightSleep = netSleep - (garmin.sleep_deep_min || 0) - (garmin.sleep_rem_min || 0);

// 3. УНИВЕРСАЛЬНЫЙ НАДЕЖНЫЙ ПАРСЕР ДАТЫ ИЗ ТАБЛИЦЫ MEALS
const parseAnyDate = (dStr) => {
  if (!dStr) return NaN;
  let s = String(dStr).trim();

  // Формат DD.MM.YYYY HH:mm:ss
  if (s.match(/^\d{1,2}\.\d{1,2}\.\d{4}/)) {
    let p = s.split(' ');
    let d = p[0].split('.');
    s = `${d[2]}-${d[1].padStart(2, '0')}-${d[0].padStart(2, '0')}T${p[1] || '00:00:00'}+10:00`;
  }
  // Формат DD/MM/YYYY HH:mm:ss
  else if (s.match(/^\d{1,2}\/\d{1,2}\/\d{4}/)) {
    let p = s.split(' ');
    let d = p[0].split('/');
    s = `${d[2]}-${d[0].padStart(2, '0')}-${d[1].padStart(2, '0')}T${p[1] || '00:00:00'}+10:00`;
  }
  // Формат ISO или с пробелом YYYY-MM-DD HH:mm:ss
  else {
    s = s.replace(' ', 'T');
    if (!s.includes('+') && !s.endsWith('Z')) s += '+10:00';
  }
  return new Date(s).getTime();
};

// 4. АНАЛИТИКА ПИТАНИЯ (СТРОГО ЗА ВЧЕРАШНИЙ ДЕНЬ)
let dinner = { time: null, kcal: 0, p: 0, f: 0, c: 0, fastWindow: null, totalFasting: null };
let dailyMacros = { kcal: 0, p: 0, f: 0, c: 0 };
let breakfastTime = null;
let totalAlcohol = 0;
let lastCoffeeTime = null;

if (nutritionList.length > 0 && startOfTodayMs > 0) {
  const allMeals = [];

  nutritionList.forEach(r => {
    // Проверяем разные возможные имена столбца с датой в Meals
    const rawDateVal = r['Date'] || r['Дата'] || r['date'];
    const ms = parseAnyDate(rawDateVal);
    if (!isNaN(ms)) {
      allMeals.push({ row: r, ms: ms, rawDate: rawDateVal });
    }
  });

  // Сортируем от самых ранних к самым поздним
  allMeals.sort((a, b) => a.ms - b.ms);

  // Фильтруем приемы пищи СТРОГО за вчерашний день (00:00:00 - 23:59:59 накануне)
  const yesterdaysMeals = allMeals.filter(m => m.ms >= startOfYesterdayMs && m.ms < endOfYesterdayMs);

  if (yesterdaysMeals.length > 0) {
    yesterdaysMeals.forEach(item => {
      const r = item.row;
      dailyMacros.kcal += Number(r['Calories'] || r['Ккал'] || r['Калории'] || 0);
      dailyMacros.p += Number(r['Proteins'] || r['Белки'] || r['Белки, гр'] || 0);
      dailyMacros.f += Number(r['Fats'] || r['Жиры'] || r['Жиры, гр'] || 0);
      dailyMacros.c += Number(r['Carbs'] || r['Углеводы'] || r['Углеводы, гр'] || 0);
      totalAlcohol += Number(r['Алкоголь'] || r['Алкоголь, гр'] || r['алкоголь, гр'] || 0);

      const caffeineVal = r['кофеин'] || r['Кофеин'];
      if (caffeineVal && String(caffeineVal).trim() !== '' && String(caffeineVal).trim() !== '0') {
        lastCoffeeTime = item.rawDate; 
      }
    });

    // Определение Ужина:
    // 1. Ищем приемы пищи после 17:00 вчера, но ДО времени отбоя btMs
    let dinnerThreshold = startOfYesterdayMs + 17 * 60 * 60 * 1000;
    let dinnerItems = yesterdaysMeals.filter(m => m.ms >= dinnerThreshold && (btMs === 0 || m.ms <= btMs));

    // 2. Если после 17:00 ничего не было, берем самый последний вчерашний прием пищи до отбоя
    if (dinnerItems.length === 0) {
      let beforeSleepMeals = yesterdaysMeals.filter(m => btMs === 0 || m.ms <= btMs);
      if (beforeSleepMeals.length > 0) {
        dinnerItems = [beforeSleepMeals[beforeSleepMeals.length - 1]];
      }
    }

    if (dinnerItems.length > 0) {
      dinnerItems.forEach(item => {
        const r = item.row;
        dinner.kcal += Number(r['Calories'] || r['Ккал'] || r['Калории'] || 0);
        dinner.p += Number(r['Proteins'] || r['Белки'] || r['Белки, гр'] || 0);
        dinner.f += Number(r['Fats'] || r['Жиры'] || r['Жиры, гр'] || 0);
        dinner.c += Number(r['Carbs'] || r['Углеводы'] || r['Углеводы, гр'] || 0);
      });
      dinner.time = dinnerItems[dinnerItems.length - 1].rawDate;
    }
  }

  // Расчет Окна голода до сна и Длительности голодания
  if (btMs > 0) {
    // Последний прием пищи перед сном (из всех записей до отбоя)
    const mealsBeforeSleep = allMeals.filter(m => m.ms <= btMs);
    if (mealsBeforeSleep.length > 0) {
      const lastMeal = mealsBeforeSleep[mealsBeforeSleep.length - 1];
      const lastMealMs = lastMeal.ms;

      // Окно голода до сна (ч)
      if ((btMs - lastMealMs) < 24 * 60 * 60 * 1000 && (btMs - lastMealMs) > 0) {
        dinner.fastWindow = rnd((btMs - lastMealMs) / (1000 * 60 * 60));
      }

      // Завтрак СЕГОДНЯ после подъема
      if (wtMs > 0) {
        const mealsAfterWake = allMeals.filter(m => m.ms >= wtMs);
        if (mealsAfterWake.length > 0) {
          const firstMeal = mealsAfterWake[0];
          breakfastTime = firstMeal.rawDate;

          if ((firstMeal.ms - lastMealMs) < 36 * 60 * 60 * 1000 && (firstMeal.ms - lastMealMs) > 0) {
            dinner.totalFasting = rnd((firstMeal.ms - lastMealMs) / (1000 * 60 * 60));
          }
        }
      }
    }
  }
}

// 5. ТРЕНИРОВКИ
let t1_type = null, t1_min = null;
let t2_type = null, t2_min = null;
let t3_type = null, t3_min = null;
let workout_kcal = 0;

if (garmin.workouts_raw) {
  const wList = garmin.workouts_raw.split(';;');
  wList.forEach((w, index) => {
    const parts = w.split('|');
    if (parts.length === 3) {
      const wName = parts[0];
      const wMin = Number(parts[1]) || 0;
      const wKcal = Number(parts[2]) || 0;
      workout_kcal += wKcal;
      if (index === 0) { t1_type = wName; t1_min = wMin; }
      else if (index === 1) { t2_type = wName; t2_min = wMin; }
      else if (index === 2) { t3_type = wName; t3_min = wMin; }
    }
  });
}

// 6. КЛИМАТ ВО ВРЕМЯ СНА (В спальне)
const getMultiVal = (row, keysArray) => {
  for (let k of keysArray) {
    if (row[k] !== undefined && row[k] !== null && String(row[k]).trim() !== '') return Number(row[k]);
  }
  return null;
};

const avgMultiClimate = (arr, keysArray) => {
  if (!arr || arr.length === 0) return null;
  let sum = 0; let count = 0;
  arr.forEach(r => {
    const rawDate = r['Дата'] || r['Date'] || r['date'];
    if (rawDate) {
      let rowTimeMs = parseAnyDate(rawDate);
      if (!isNaN(rowTimeMs)) {
        if (btMs > 0 && wtMs > 0) {
          if (rowTimeMs < btMs || rowTimeMs > wtMs) return; // Строго в часы сна
        } else if (startOfYesterdayMs > 0) {
          if (rowTimeMs < startOfYesterdayMs || rowTimeMs > endOfYesterdayMs) return;
        }
      }
    }
    const val = getMultiVal(r, keysArray);
    if (val !== null && !isNaN(val)) { sum += val; count++; }
  });
  return count > 0 ? rnd(sum / count) : null;
};

const avgTempC = avgMultiClimate(climateRecords, ['temp', 'Temp', 'Температура', 'температура', 'Temperature']);
const avgHumPct = avgMultiClimate(climateRecords, ['humidity', 'Humidity', 'Влажность', 'влажность']);
const avgPM25 = avgMultiClimate(climateRecords, ['pm25', 'PM25', 'PM2.5', 'pm 2.5']);
const dewPointRecords = getSafeArray('Точка росы');
const avgDewPoint = avgMultiClimate(dewPointRecords, ['Точка_росы_avg_C', 'Точка росы', 'dew_point', 'DewPoint']);

// 7. ЛЕКАРСТВА
let medsList = [];
if (calendarItems.length > 0) {
  calendarItems.forEach(event => {
    const title = (event.summary || event.text || '').toLowerCase();
    if (title && (title.includes('мг') || title.includes('таб') || title.includes('капс') || /\d+/.test(title))) {
      if (!title.includes('встреча') && !title.includes('позвонить')) medsList.push((event.summary || event.text).trim());
    }
  });
}

// 8. ДАВЛЕНИЕ
let avgNightPressure = null;
if (weather && weather.hourly && weather.hourly.time && weather.hourly.surface_pressure && btMs > 0 && wtMs > 0) {
  let pressSum = 0; let pressCount = 0;
  for (let i = 0; i < weather.hourly.time.length; i++) {
    const tMs = new Date(String(weather.hourly.time[i]) + '+10:00').getTime();
    if (tMs >= btMs && tMs <= wtMs) { pressSum += Number(weather.hourly.surface_pressure[i]); pressCount++; }
  }
  if (pressCount > 0) avgNightPressure = rnd(pressSum / pressCount);
}

// 9. RESCUETIME (Экранное время за вчера)
let screenTotalSec = 0; let screenProdSec = 0; let screenDistractSec = 0;
let screenBeforeBedSec = 0;
let deepWorkSeconds = 0; let lightWorkSeconds = 0;

if (rescueData && rescueData.rows) {
  rescueData.rows.forEach(row => {
    const rTimeStr = String(row[0]);
    const timeSpent = row[1];
    const prodLevel = row[3];

    let rMs = parseAnyDate(rTimeStr);

    if (!isNaN(rMs) && rMs >= startOfYesterdayMs && rMs < endOfYesterdayMs) {
      screenTotalSec += timeSpent;
      if (prodLevel > 0) screenProdSec += timeSpent; else if (prodLevel < 0) screenDistractSec += timeSpent;
      if (prodLevel === 2) deepWorkSeconds += timeSpent;
      else if (prodLevel === 1) lightWorkSeconds += timeSpent;
    }

    if (btMs > 0 && !isNaN(rMs) && rMs <= btMs && (rMs + 3600 * 1000) > (btMs - 2 * 60 * 60 * 1000)) {
      screenBeforeBedSec += timeSpent;
    }
  });
}

let cognitiveLoadIndex = null;
if (screenTotalSec > 0) {
  const deepWorkHours = deepWorkSeconds / 3600;
  const lightWorkHours = lightWorkSeconds / 3600;
  const cognitiveLoadScore = (deepWorkHours * 1.5) + (lightWorkHours * 0.5);
  cognitiveLoadIndex = rnd(Math.min((cognitiveLoadScore / 12) * 10, 10));
}

// 10. ИТОГОВЫЙ ОБЪЕКТ ДЛЯ ЗАПИСИ
return {
  "Дата": garmin.date || null,
  "Время_отбоя": garmin.bedtime || null,
  "Время_подъема": garmin.wakeup_time || null,
  "Время_в_кровати_мин": inBed,
  "Чистый_сон_мин": netSleep,
  "Эффективность_сна_": inBed > 0 ? rnd((netSleep / inBed) * 100) + '%' : null,
  "Оценка_сна_балл": garmin.sleep_score || null,

  "Глубокий_сон_мин": garmin.sleep_deep_min || 0,
  "Глубокий_1_половина_мин": garmin.deep1_min || 0,
  "Глубокий_2_половина_мин": garmin.deep2_min || 0,
  "REM_сон_мин": garmin.sleep_rem_min || 0,
  "Легкий_сон_мин": lightSleep > 0 ? lightSleep : 0,

  "Пробуждения_кол_во": garmin.awake_count || 0,
  "Беспокойные_моменты": garmin.restless_moments || 0,
  "Бодрствование_мин": awake,

  "Пульс_ночной_средний": garmin.hr_night_avg || null,
  "Пульс_ночной_мин": garmin.hr_night_min || null,
  "Пульс_ночной_макс": garmin.hr_night_max || null,
  "ВСР_ночная": garmin.hrv_night || null,

  "Дыхание_ночь_среднее": garmin.respiration_avg || null,
  "SpO2_ночь_среднее": garmin.spo2_avg || null,
  "Восстановление_BodyBattery": garmin.body_battery_recharge || null,
  "Стресс_дневной_средний": garmin.day_stress_avg || null,

  "Температура_avg_C": avgTempC,
  "Влажность_avg_%": avgHumPct,
  "Точка_росы_avg_C": avgDewPoint,
  "PM25_avg": avgPM25,

  "Питание_Всего_Ккал": rnd(dailyMacros.kcal),
  "Питание_Всего_Белки_г": rnd(dailyMacros.p),
  "Питание_Всего_Жиры_г": rnd(dailyMacros.f),
  "Питание_Всего_Углеводы_г": rnd(dailyMacros.c),

  "Время_последнего_кофе": lastCoffeeTime,

  "Ужин_время": dinner.time,
  "Окно_голода_до_сна_ч": dinner.fastWindow,
  "Завтрак_время": breakfastTime,
  "Длительность_голода_ч": dinner.totalFasting,
  "Ужин_Ккал": rnd(dinner.kcal),
  "Ужин_Белки_г": rnd(dinner.p),
  "Ужин_Жиры_г": rnd(dinner.f),
  "Ужин_Углеводы_г": rnd(dinner.c),
  "Алкоголь_гр": rnd(totalAlcohol),

  "Шаги_за_вчера": (garmin.steps === undefined || garmin.steps === null || garmin.steps === "") ? null : garmin.steps,
  "VO2_Max": garmin.vo2max || null,

  "Тренировка_1_Тип": t1_type || 'Нет',
  "Тренировка_1_Мин": t1_min,
  "Тренировка_2_Тип": t2_type,
  "Тренировка_2_Мин": t2_min,
  "Тренировка_3_Тип": t3_type,
  "Тренировка_3_Мин": t3_min,
  "Тренировка_Ккал": workout_kcal > 0 ? workout_kcal : null,

  "Тренировка_поздняя": garmin.late_workout_flag ? "Да" : "Нет",
  "Дыхание_тип": garmin.breathwork_type || 'Нет',
  "Дыхание_мин": garmin.breathwork_min || 0,

  "Атмосферное_давление_ночь_hPa": avgNightPressure,
  "Атм_давление_Дельта_12ч": weatherDeltas.pressure_delta_12h !== undefined ? rnd(weatherDeltas.pressure_delta_12h) : null,
  "Атм_давление_Дельта_24ч": weatherDeltas.pressure_delta_24h !== undefined ? rnd(weatherDeltas.pressure_delta_24h) : null,
  "Освещенность_ч_сутки": weatherDeltas.sunshine_hours_last_24h !== undefined ? weatherDeltas.sunshine_hours_last_24h : null,
  "Лекарства_принимаемые": medsList.length > 0 ? medsList.join('\n') : null,

  "Экранное_время_всего_ч": screenTotalSec > 0 ? rnd(screenTotalSec / 3600) : null,
  "Экран_Продуктивно_ч": screenProdSec > 0 ? rnd(screenProdSec / 3600) : null,
  "Экран_Отвлечения_ч": screenDistractSec > 0 ? rnd(screenDistractSec / 3600) : null,
  "Экран_перед_сном_мин": rnd(screenBeforeBedSec / 60),
  "Индекс_когнитивной_нагрузки": cognitiveLoadIndex,

  "Темп_тренировки_avg_C": garmin.temp_activity_avg_c || null,
  "Темп_тренировки_min_C": garmin.temp_activity_min_c || null,
  "Темп_тренировки_max_C": garmin.temp_activity_max_c || null,
  "Training_Status": garmin.training_status || null,
  "Training_Acute_Load": garmin.training_acute_load || null,
  "Training_Chronic_Load": garmin.training_chronic_load || null
};

// Получаем все входящие элементы (строки из Google Таблицы)
const items = $input.all();

// Константы формулы Магнуса
const a = 17.27;
const b = 237.7;

// Проходим циклом по каждому элементу
for (const item of items) {
  const tempCelsius = item.json["Температура"];
  const relativeHumidity = item.json["Влажность"];

  // Проверяем, существуют ли числовые данные, чтобы скрипт не упал на пустой строке
  if (typeof tempCelsius === 'number' && typeof relativeHumidity === 'number') {

    // Математика: расчет точки росы
    const alpha = ((a * tempCelsius) / (b + tempCelsius)) + Math.log(relativeHumidity / 100.0);
    const dewPoint = (b * alpha) / (a - alpha);

    // Добавляем новое поле в JSON текущего элемента
    item.json["Точка росы"] = parseFloat(dewPoint.toFixed(2));
  }
}

// Возвращаем обогащенный массив дальше по цепочке
return items;

const hourlyData = $input.first().json.hourly;
const pressureArray = hourlyData.surface_pressure;
const timeArray = hourlyData.time;

// Находим индекс часа, ближайшего к текущему моменту (вместо жёсткого 24)
const now = new Date();
let currentHourIndex = timeArray.findIndex(t => {
  const hourTime = new Date(t);
  return hourTime.getUTCFullYear() === now.getUTCFullYear() &&
         hourTime.getUTCMonth() === now.getUTCMonth() &&
         hourTime.getUTCDate() === now.getUTCDate() &&
         hourTime.getUTCHours() === now.getUTCHours();
});

if (currentHourIndex === -1) currentHourIndex = Math.floor(timeArray.length / 2);
if (currentHourIndex < 24) currentHourIndex = 24;

const currentPressure = pressureArray[currentHourIndex];
const pressure24hAgo = pressureArray[currentHourIndex - 24];
const pressure12hAgo = pressureArray[currentHourIndex - 12];

const delta24h = currentPressure - pressure24hAgo;
const delta12h = currentPressure - pressure12hAgo;

// Суммарная продолжительность солнечного сияния за прошедшие 24 часа (в секундах)
let sunshineTotalSec = 0;
for (let i = currentHourIndex - 24; i < currentHourIndex; i++) {
  sunshineTotalSec += hourlyData.sunshine_duration[i] || 0;
}
const sunshineHours = Math.round((sunshineTotalSec / 3600) * 10) / 10;

return {
  json: {
    current_pressure: currentPressure,
    pressure_delta_24h: delta24h,
    pressure_delta_12h: delta12h,
    sunshine_hours_last_24h: sunshineHours,
  }
};

// 1. ИНИЦИАЛИЗАЦИЯ ДАННЫХ
function getSafeArray(nodeName) {
  try { return $(nodeName).all().map(item => item.json); } catch (e) { return []; }
}
function getSafeFirst(nodeName) {
  try { const data = $(nodeName).all(); return data.length > 0 ? data[0].json : {}; } catch (e) { return {}; }
}

let garminNode = getSafeFirst('Webhook') || {};
if (Object.keys(garminNode).length === 0) garminNode = getSafeFirst('Webhook1');
let garmin = garminNode.body || garminNode;

const nutritionList = getSafeArray('Get Nutrition');
const climateRecords = getSafeArray('Get Climate');
const calendarItems = getSafeArray('Get Calendar Events');
const rescueData = getSafeFirst('Get RescueTime');

const weather = getSafeFirst('Get Weather'); 
const weatherDeltas = getSafeFirst('Перепады давления');

const rnd = (val) => (val !== null && val !== undefined && !isNaN(val) && val !== '') ? Math.round(Number(val) * 10) / 10 : null;

// 2. ДАТЫ И ВРЕМЕННЫЕ МЕТКИ
let btMs = 0; 
let wtMs = 0;

if (garmin.bedtime && garmin.wakeup_time) {
  let btStr = String(garmin.bedtime).replace(' ', 'T');
  if (!btStr.includes('+') && !btStr.endsWith('Z')) btStr += '+10:00';
  btMs = new Date(btStr).getTime();

  let wtStr = String(garmin.wakeup_time).replace(' ', 'T');
  if (!wtStr.includes('+') && !wtStr.endsWith('Z')) wtStr += '+10:00';
  wtMs = new Date(wtStr).getTime();
}

// Дата строки пробуждения (например, 2026-08-19)
let todayStr = garmin.date;
let startOfTodayMs = todayStr ? new Date(`${todayStr}T00:00:00+10:00`).getTime() : 0;

// Вчерашний день (сутки накануне сна: 2026-08-18 00:00 - 23:59)
let startOfYesterdayMs = startOfTodayMs - 24 * 60 * 60 * 1000;
let endOfYesterdayMs = startOfTodayMs;

const netSleep = garmin.sleep_total_min || 0;
const awake = garmin.awake_time_min || 0;
const inBed = netSleep + awake;
const lightSleep = netSleep - (garmin.sleep_deep_min || 0) - (garmin.sleep_rem_min || 0);

// 3. УНИВЕРСАЛЬНЫЙ НАДЕЖНЫЙ ПАРСЕР ДАТЫ ИЗ ТАБЛИЦЫ MEALS
const parseAnyDate = (dStr) => {
  if (!dStr) return NaN;
  let s = String(dStr).trim();

  // Формат DD.MM.YYYY HH:mm:ss
  if (s.match(/^\d{1,2}\.\d{1,2}\.\d{4}/)) {
    let p = s.split(' ');
    let d = p[0].split('.');
    s = `${d[2]}-${d[1].padStart(2, '0')}-${d[0].padStart(2, '0')}T${p[1] || '00:00:00'}+10:00`;
  }
  // Формат DD/MM/YYYY HH:mm:ss
  else if (s.match(/^\d{1,2}\/\d{1,2}\/\d{4}/)) {
    let p = s.split(' ');
    let d = p[0].split('/');
    s = `${d[2]}-${d[0].padStart(2, '0')}-${d[1].padStart(2, '0')}T${p[1] || '00:00:00'}+10:00`;
  }
  // Формат ISO или с пробелом YYYY-MM-DD HH:mm:ss
  else {
    s = s.replace(' ', 'T');
    if (!s.includes('+') && !s.endsWith('Z')) s += '+10:00';
  }
  return new Date(s).getTime();
};

// 4. АНАЛИТИКА ПИТАНИЯ (СТРОГО ЗА ВЧЕРАШНИЙ ДЕНЬ)
let dinner = { time: null, kcal: 0, p: 0, f: 0, c: 0, fastWindow: null, totalFasting: null };
let dailyMacros = { kcal: 0, p: 0, f: 0, c: 0 };
let breakfastTime = null;
let totalAlcohol = 0;
let lastCoffeeTime = null;

if (nutritionList.length > 0 && startOfTodayMs > 0) {
  const allMeals = [];

  nutritionList.forEach(r => {
    // Проверяем разные возможные имена столбца с датой в Meals
    const rawDateVal = r['Date'] || r['Дата'] || r['date'];
    const ms = parseAnyDate(rawDateVal);
    if (!isNaN(ms)) {
      allMeals.push({ row: r, ms: ms, rawDate: rawDateVal });
    }
  });

  // Сортируем от самых ранних к самым поздним
  allMeals.sort((a, b) => a.ms - b.ms);

  // Фильтруем приемы пищи СТРОГО за вчерашний день (00:00:00 - 23:59:59 накануне)
  const yesterdaysMeals = allMeals.filter(m => m.ms >= startOfYesterdayMs && m.ms < endOfYesterdayMs);

  if (yesterdaysMeals.length > 0) {
    yesterdaysMeals.forEach(item => {
      const r = item.row;
      dailyMacros.kcal += Number(r['Calories'] || r['Ккал'] || r['Калории'] || 0);
      dailyMacros.p += Number(r['Proteins'] || r['Белки'] || r['Белки, гр'] || 0);
      dailyMacros.f += Number(r['Fats'] || r['Жиры'] || r['Жиры, гр'] || 0);
      dailyMacros.c += Number(r['Carbs'] || r['Углеводы'] || r['Углеводы, гр'] || 0);
      totalAlcohol += Number(r['Алкоголь, гр'] || r['алкоголь, гр'] || 0);

      const caffeineVal = r['кофеин'] || r['Кофеин'];
      if (caffeineVal && String(caffeineVal).trim() !== '' && String(caffeineVal).trim() !== '0') {
        lastCoffeeTime = item.rawDate; 
      }
    });

    // Определение Ужина:
    // 1. Ищем приемы пищи после 17:00 вчера, но ДО времени отбоя btMs
    let dinnerThreshold = startOfYesterdayMs + 17 * 60 * 60 * 1000;
    let dinnerItems = yesterdaysMeals.filter(m => m.ms >= dinnerThreshold && (btMs === 0 || m.ms <= btMs));

    // 2. Если после 17:00 ничего не было, берем самый последний вчерашний прием пищи до отбоя
    if (dinnerItems.length === 0) {
      let beforeSleepMeals = yesterdaysMeals.filter(m => btMs === 0 || m.ms <= btMs);
      if (beforeSleepMeals.length > 0) {
        dinnerItems = [beforeSleepMeals[beforeSleepMeals.length - 1]];
      }
    }

    if (dinnerItems.length > 0) {
      dinnerItems.forEach(item => {
        const r = item.row;
        dinner.kcal += Number(r['Calories'] || r['Ккал'] || r['Калории'] || 0);
        dinner.p += Number(r['Proteins'] || r['Белки'] || r['Белки, гр'] || 0);
        dinner.f += Number(r['Fats'] || r['Жиры'] || r['Жиры, гр'] || 0);
        dinner.c += Number(r['Carbs'] || r['Углеводы'] || r['Углеводы, гр'] || 0);
      });
      dinner.time = dinnerItems[dinnerItems.length - 1].rawDate;
    }
  }

  // Расчет Окна голода до сна и Длительности голодания
  if (btMs > 0) {
    // Последний прием пищи перед сном (из всех записей до отбоя)
    const mealsBeforeSleep = allMeals.filter(m => m.ms <= btMs);
    if (mealsBeforeSleep.length > 0) {
      const lastMeal = mealsBeforeSleep[mealsBeforeSleep.length - 1];
      const lastMealMs = lastMeal.ms;

      // Окно голода до сна (ч)
      if ((btMs - lastMealMs) < 24 * 60 * 60 * 1000 && (btMs - lastMealMs) > 0) {
        dinner.fastWindow = rnd((btMs - lastMealMs) / (1000 * 60 * 60));
      }

      // Завтрак СЕГОДНЯ после подъема
      if (wtMs > 0) {
        const mealsAfterWake = allMeals.filter(m => m.ms >= wtMs);
        if (mealsAfterWake.length > 0) {
          const firstMeal = mealsAfterWake[0];
          breakfastTime = firstMeal.rawDate;

          if ((firstMeal.ms - lastMealMs) < 36 * 60 * 60 * 1000 && (firstMeal.ms - lastMealMs) > 0) {
            dinner.totalFasting = rnd((firstMeal.ms - lastMealMs) / (1000 * 60 * 60));
          }
        }
      }
    }
  }
}

// 5. ТРЕНИРОВКИ
let t1_type = null, t1_min = null;
let t2_type = null, t2_min = null;
let t3_type = null, t3_min = null;
let workout_kcal = 0;

if (garmin.workouts_raw) {
  const wList = garmin.workouts_raw.split(';;');
  wList.forEach((w, index) => {
    const parts = w.split('|');
    if (parts.length === 3) {
      const wName = parts[0];
      const wMin = Number(parts[1]) || 0;
      const wKcal = Number(parts[2]) || 0;
      workout_kcal += wKcal;
      if (index === 0) { t1_type = wName; t1_min = wMin; }
      else if (index === 1) { t2_type = wName; t2_min = wMin; }
      else if (index === 2) { t3_type = wName; t3_min = wMin; }
    }
  });
}

// 6. КЛИМАТ ВО ВРЕМЯ СНА (В спальне)
const getMultiVal = (row, keysArray) => {
  for (let k of keysArray) {
    if (row[k] !== undefined && row[k] !== null && String(row[k]).trim() !== '') return Number(row[k]);
  }
  return null;
};

const avgMultiClimate = (arr, keysArray) => {
  if (!arr || arr.length === 0) return null;
  let sum = 0; let count = 0;
  arr.forEach(r => {
    const rawDate = r['Дата'] || r['Date'] || r['date'];
    if (rawDate) {
      let rowTimeMs = parseAnyDate(rawDate);
      if (!isNaN(rowTimeMs)) {
        if (btMs > 0 && wtMs > 0) {
          if (rowTimeMs < btMs || rowTimeMs > wtMs) return; // Строго в часы сна
        } else if (startOfYesterdayMs > 0) {
          if (rowTimeMs < startOfYesterdayMs || rowTimeMs > endOfYesterdayMs) return;
        }
      }
    }
    const val = getMultiVal(r, keysArray);
    if (val !== null && !isNaN(val)) { sum += val; count++; }
  });
  return count > 0 ? rnd(sum / count) : null;
};

const avgTempC = avgMultiClimate(climateRecords, ['temp', 'Temp', 'Температура', 'температура', 'Temperature']);
const avgHumPct = avgMultiClimate(climateRecords, ['humidity', 'Humidity', 'Влажность', 'влажность']);
const avgPM25 = avgMultiClimate(climateRecords, ['pm25', 'PM25', 'PM2.5', 'pm 2.5']);
const dewPointRecords = getSafeArray('Точка росы');
const avgDewPoint = avgMultiClimate(dewPointRecords, ['Точка_росы_avg_C', 'Точка росы', 'dew_point', 'DewPoint']);

// 7. ЛЕКАРСТВА
let medsList = [];
if (calendarItems.length > 0) {
  calendarItems.forEach(event => {
    const title = (event.summary || event.text || '').toLowerCase();
    if (title && (title.includes('мг') || title.includes('таб') || title.includes('капс') || /\d+/.test(title))) {
      if (!title.includes('встреча') && !title.includes('позвонить')) medsList.push((event.summary || event.text).trim());
    }
  });
}

// 8. ДАВЛЕНИЕ
let avgNightPressure = null;
if (weather && weather.hourly && weather.hourly.time && weather.hourly.surface_pressure && btMs > 0 && wtMs > 0) {
  let pressSum = 0; let pressCount = 0;
  for (let i = 0; i < weather.hourly.time.length; i++) {
    const tMs = new Date(String(weather.hourly.time[i]) + '+10:00').getTime();
    if (tMs >= btMs && tMs <= wtMs) { pressSum += Number(weather.hourly.surface_pressure[i]); pressCount++; }
  }
  if (pressCount > 0) avgNightPressure = rnd(pressSum / pressCount);
}

// 9. RESCUETIME (Экранное время за вчера)
let screenTotalSec = 0; let screenProdSec = 0; let screenDistractSec = 0;
let screenBeforeBedSec = 0;
let deepWorkSeconds = 0; let lightWorkSeconds = 0;

if (rescueData && rescueData.rows) {
  rescueData.rows.forEach(row => {
    const rTimeStr = String(row[0]);
    const timeSpent = row[1];
    const prodLevel = row[3];

    let rMs = parseAnyDate(rTimeStr);

    if (!isNaN(rMs) && rMs >= startOfYesterdayMs && rMs < endOfYesterdayMs) {
      screenTotalSec += timeSpent;
      if (prodLevel > 0) screenProdSec += timeSpent; else if (prodLevel < 0) screenDistractSec += timeSpent;
      if (prodLevel === 2) deepWorkSeconds += timeSpent;
      else if (prodLevel === 1) lightWorkSeconds += timeSpent;
    }

    if (btMs > 0 && !isNaN(rMs) && rMs <= btMs && (rMs + 3600 * 1000) > (btMs - 2 * 60 * 60 * 1000)) {
      screenBeforeBedSec += timeSpent;
    }
  });
}

let cognitiveLoadIndex = null;
if (screenTotalSec > 0) {
  const deepWorkHours = deepWorkSeconds / 3600;
  const lightWorkHours = lightWorkSeconds / 3600;
  const cognitiveLoadScore = (deepWorkHours * 1.5) + (lightWorkHours * 0.5);
  cognitiveLoadIndex = rnd(Math.min((cognitiveLoadScore / 12) * 10, 10));
}

// 10. ИТОГОВЫЙ ОБЪЕКТ ДЛЯ ЗАПИСИ
return {
  "Дата": garmin.date || null,
  "Время_отбоя": garmin.bedtime || null,
  "Время_подъема": garmin.wakeup_time || null,
  "Время_в_кровати_мин": inBed,
  "Чистый_сон_мин": netSleep,
  "Эффективность_сна_": inBed > 0 ? rnd((netSleep / inBed) * 100) + '%' : null,
  "Оценка_сна_балл": garmin.sleep_score || null,

  "Глубокий_сон_мин": garmin.sleep_deep_min || 0,
  "Глубокий_1_половина_мин": garmin.deep1_min || 0,
  "Глубокий_2_половина_мин": garmin.deep2_min || 0,
  "REM_сон_мин": garmin.sleep_rem_min || 0,
  "Легкий_сон_мин": lightSleep > 0 ? lightSleep : 0,

  "Пробуждения_кол_во": garmin.awake_count || 0,
  "Беспокойные_моменты": garmin.restless_moments || 0,
  "Бодрствование_мин": awake,

  "Пульс_ночной_средний": garmin.hr_night_avg || null,
  "Пульс_ночной_мин": garmin.hr_night_min || null,
  "Пульс_ночной_макс": garmin.hr_night_max || null,
  "ВСР_ночная": garmin.hrv_night || null,

  "Дыхание_ночь_среднее": garmin.respiration_avg || null,
  "SpO2_ночь_среднее": garmin.spo2_avg || null,
  "Восстановление_BodyBattery": garmin.body_battery_recharge || null,
  "Стресс_дневной_средний": garmin.day_stress_avg || null,

  "Температура_avg_C": avgTempC,
  "Влажность_avg_%": avgHumPct,
  "Точка_росы_avg_C": avgDewPoint,
  "PM25_avg": avgPM25,

  "Питание_Всего_Ккал": rnd(dailyMacros.kcal),
  "Питание_Всего_Белки_г": rnd(dailyMacros.p),
  "Питание_Всего_Жиры_г": rnd(dailyMacros.f),
  "Питание_Всего_Углеводы_г": rnd(dailyMacros.c),

  "Время_последнего_кофе": lastCoffeeTime,

  "Ужин_время": dinner.time,
  "Окно_голода_до_сна_ч": dinner.fastWindow,
  "Завтрак_время": breakfastTime,
  "Длительность_голода_ч": dinner.totalFasting,
  "Ужин_Ккал": rnd(dinner.kcal),
  "Ужин_Белки_г": rnd(dinner.p),
  "Ужин_Жиры_г": rnd(dinner.f),
  "Ужин_Углеводы_г": rnd(dinner.c),
  "Алкоголь_гр": rnd(totalAlcohol),

  "Шаги_за_вчера": garmin.steps || 0,
  "VO2_Max": garmin.vo2max || null,

  "Тренировка_1_Тип": t1_type || 'Нет',
  "Тренировка_1_Мин": t1_min,
  "Тренировка_2_Тип": t2_type,
  "Тренировка_2_Мин": t2_min,
  "Тренировка_3_Тип": t3_type,
  "Тренировка_3_Мин": t3_min,
  "Тренировка_Ккал": workout_kcal > 0 ? workout_kcal : null,

  "Тренировка_поздняя": garmin.late_workout_flag ? "Да" : "Нет",
  "Дыхание_тип": garmin.breathwork_type || 'Нет',
  "Дыхание_мин": garmin.breathwork_min || 0,

  "Атмосферное_давление_ночь_hPa": avgNightPressure,
  "Атм_давление_Дельта_12ч": weatherDeltas.pressure_delta_12h !== undefined ? rnd(weatherDeltas.pressure_delta_12h) : null,
  "Атм_давление_Дельта_24ч": weatherDeltas.pressure_delta_24h !== undefined ? rnd(weatherDeltas.pressure_delta_24h) : null,
  "Освещенность_ч_сутки": weatherDeltas.sunshine_hours_last_24h !== undefined ? weatherDeltas.sunshine_hours_last_24h : null,
  "Лекарства_принимаемые": medsList.length > 0 ? medsList.join('\n') : null,

  "Экранное_время_всего_ч": screenTotalSec > 0 ? rnd(screenTotalSec / 3600) : null,
  "Экран_Продуктивно_ч": screenProdSec > 0 ? rnd(screenProdSec / 3600) : null,
  "Экран_Отвлечения_ч": screenDistractSec > 0 ? rnd(screenDistractSec / 3600) : null,
  "Экран_перед_сном_мин": rnd(screenBeforeBedSec / 60),
  "Индекс_когнитивной_нагрузки": cognitiveLoadIndex,

  "Темп_тренировки_avg_C": garmin.temp_activity_avg_c || null,
  "Темп_тренировки_min_C": garmin.temp_activity_min_c || null,
  "Темп_тренировки_max_C": garmin.temp_activity_max_c || null,
  "Training_Status": garmin.training_status || null,
  "Training_Acute_Load": garmin.training_acute_load || null,
  "Training_Chronic_Load": garmin.training_chronic_load || null
};

// Получаем все входящие элементы (строки из Google Таблицы)
const items = $input.all();

// Константы формулы Магнуса
const a = 17.27;
const b = 237.7;

// Проходим циклом по каждому элементу
for (const item of items) {
  const tempCelsius = item.json["Температура"];
  const relativeHumidity = item.json["Влажность"];

  // Проверяем, существуют ли числовые данные, чтобы скрипт не упал на пустой строке
  if (typeof tempCelsius === 'number' && typeof relativeHumidity === 'number') {

    // Математика: расчет точки росы
    const alpha = ((a * tempCelsius) / (b + tempCelsius)) + Math.log(relativeHumidity / 100.0);
    const dewPoint = (b * alpha) / (a - alpha);

    // Добавляем новое поле в JSON текущего элемента
    item.json["Точка росы"] = parseFloat(dewPoint.toFixed(2));
  }
}

// Возвращаем обогащенный массив дальше по цепочке
return items;

const hourlyData = $input.first().json.hourly;
const pressureArray = hourlyData.surface_pressure;
const timeArray = hourlyData.time;

// Находим индекс часа, ближайшего к текущему моменту (вместо жёсткого 24)
const now = new Date();
let currentHourIndex = timeArray.findIndex(t => {
  const hourTime = new Date(t);
  return hourTime.getUTCFullYear() === now.getUTCFullYear() &&
         hourTime.getUTCMonth() === now.getUTCMonth() &&
         hourTime.getUTCDate() === now.getUTCDate() &&
         hourTime.getUTCHours() === now.getUTCHours();
});

if (currentHourIndex === -1) currentHourIndex = Math.floor(timeArray.length / 2);
if (currentHourIndex < 24) currentHourIndex = 24;

const currentPressure = pressureArray[currentHourIndex];
const pressure24hAgo = pressureArray[currentHourIndex - 24];
const pressure12hAgo = pressureArray[currentHourIndex - 12];

const delta24h = currentPressure - pressure24hAgo;
const delta12h = currentPressure - pressure12hAgo;

// Суммарная продолжительность солнечного сияния за прошедшие 24 часа (в секундах)
let sunshineTotalSec = 0;
for (let i = currentHourIndex - 24; i < currentHourIndex; i++) {
  sunshineTotalSec += hourlyData.sunshine_duration[i] || 0;
}
const sunshineHours = Math.round((sunshineTotalSec / 3600) * 10) / 10;

return {
  json: {
    current_pressure: currentPressure,
    pressure_delta_24h: delta24h,
    pressure_delta_12h: delta12h,
    sunshine_hours_last_24h: sunshineHours,
  }
};
